SELECT inventory.id, inventory.product_id, inventory.store_id, store_sales.product_id store_sale_product_id, store_sales.sale_date, store_sales.revenue FROM inventory LEFT JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE store_sales.product_id = 4 ORDER BY inventory.id ASC;
